const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');}));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false');});b.classList.add('active');b.setAttribute('aria-pressed','true');document.querySelectorAll('[data-category]').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.category!==b.dataset.filter);}));document.querySelectorAll('[data-select]').forEach(a=>a.addEventListener('click',()=>document.querySelector('#experience').value=a.dataset.select));document.querySelectorAll('[data-tour]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#experience').value=b.dataset.tour;document.querySelector('#booking').scrollIntoView({behavior:'smooth'});}));const date=document.querySelector('#date');const now=new Date();date.min=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');document.querySelector('#trip-form').addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;const text=`Hello Phoenix Tours! I'd like to enquire about ${document.querySelector('#experience').value} on ${date.value} for ${document.querySelector('#guests').value}. Please share availability, pricing and inclusions.`;window.open('https://wa.me/971561505270?text='+encodeURIComponent(text),'_blank','noopener');});document.querySelector('#year').textContent=now.getFullYear();
